using System;using System.Data;namespace AQOONHUB_SMS.Modules.Finance{public partial class PrintReceipt:System.Web.UI.Page{protected void Page_Load(object s,EventArgs e){if(Session["UserID"]==null)Response.Redirect("~/Modules/Authentication/Login.aspx");if(IsPostBack)return;int id;if(!int.TryParse(Request.QueryString["id"],out id))Response.Redirect("FeeManagement.aspx");DataTable d=new FeeRepository().GetPayment(id);if(d.Rows.Count==0)Response.Redirect("FeeManagement.aspx");details.DataSource=d;details.DataBind();invoiceLink.NavigateUrl="PrintInvoice.aspx?id="+d.Rows[0]["InvoiceID"];}}}
